import CoreGraphics
import Foundation
import ImageIO

func load(_ path: String) -> (w: Int, h: Int, px: [UInt8])? {
    guard let src = CGImageSourceCreateWithURL(URL(fileURLWithPath: path) as CFURL, nil),
          let img = CGImageSourceCreateImageAtIndex(src, 0, nil) else { return nil }
    let w = img.width, h = img.height
    var px = [UInt8](repeating: 0, count: w * h * 4)
    guard let ctx = CGContext(
        data: &px, width: w, height: h, bitsPerComponent: 8, bytesPerRow: w * 4,
        space: CGColorSpaceCreateDeviceRGB(),
        bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
    ) else { return nil }
    ctx.draw(img, in: CGRect(x: 0, y: 0, width: w, height: h))
    return (w, h, px)
}

let args = CommandLine.arguments
guard args.count == 3, let a = load(args[1]), let b = load(args[2]) else {
    print("usage: pngdiff <ref.png> <new.png>"); exit(2)
}
guard a.w == b.w, a.h == b.h else {
    print("SIZE MISMATCH: \(a.w)x\(a.h) vs \(b.w)x\(b.h)"); exit(1)
}

var differing = 0, maxDelta = 0
var minX = Int.max, minY = Int.max, maxX = -1, maxY = -1
for y in 0 ..< a.h {
    for x in 0 ..< a.w {
        let i = (y * a.w + x) * 4
        var d = 0
        for c in 0 ..< 4 { d = max(d, abs(Int(a.px[i + c]) - Int(b.px[i + c]))) }
        if d > 0 {
            differing += 1
            maxDelta = max(maxDelta, d)
            minX = min(minX, x); maxX = max(maxX, x)
            minY = min(minY, y); maxY = max(maxY, y)
        }
    }
}
let total = a.w * a.h
if differing == 0 {
    print("IDENTICAL (\(a.w)x\(a.h))")
} else {
    let pct = Double(differing) / Double(total) * 100
    print("size \(a.w)x\(a.h)  differing \(differing)/\(total) (\(String(format: "%.4f", pct))%)  maxDelta \(maxDelta)")
    print("bbox x \(minX)…\(maxX) (w \(maxX - minX + 1))  y \(minY)…\(maxY) (h \(maxY - minY + 1))")
}

